  static class TaskF {
    int n;
    char[] s;
    int[] beauty;

    public void solve(int testNumber, BufferedReader br, PrintWriter out) throws IOException {
      n = Integer.parseInt(br.readLine());
      s = br.readLine().toCharArray();
      beauty = new int[n];
      String[] parts = br.readLine().split(" ");
      int totalBeauty = 0;
      for (int i = 0; i < n; i++) {
        beauty[i] = Integer.parseInt(parts[i]);
        totalBeauty += beauty[i];
      }

      List<Integer> equalPairs = new ArrayList<>();
      int[] charOccurrencesInEqualPairs = new int[128];
      char mostCommonCharInEqualPairs = 'a';

      for (int i = 0; i < n / 2; i++) {
        if (s[i] == s[n - 1 - i]) {
          equalPairs.add(i);
          if (++charOccurrencesInEqualPairs[s[i]] > charOccurrencesInEqualPairs[mostCommonCharInEqualPairs]) {
            mostCommonCharInEqualPairs = s[i];
          }
        }
      }

      int ans = totalBeauty;
