        ans -= Math.min(beauty[equalPair], beauty[n - 1 - equalPair]);
      }

      if (charOccurrencesInEqualPairs[mostCommonCharInEqualPairs] > equalPairs.size() / 2) {
        List<Integer> nonEqualPairsMinBeautyPenalties = new ArrayList<>();
