#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    vector<int> beauty(n);
    int totalBeauty = 0;
    for (int i = 0; i < n; i++) {
        cin >> beauty[i];
        totalBeauty += beauty[i];
    }

    vector<int> equalPairs;
    int charOccurrencesInEqualPairs[128] = {0};
    char mostCommonCharInEqualPairs = 'a';

    for (int i = 0; i < n / 2; i++) {
        if (s[i] == s[n - 1 - i]) {
            equalPairs.push_back(i);
            if (++charOccurrencesInEqualPairs[(int)s[i]] > charOccurrencesInEqualPairs[(int)mostCommonCharInEqualPairs]) {
                mostCommonCharInEqualPairs = s[i];
            }
        }
    }

    int ans = totalBeauty;
    for (int equalPair : equalPairs) {
        ans -= std::min(beauty[equalPair], beauty[n - 1 - equalPair]);
    }

    if (charOccurrencesInEqualPairs[(int)mostCommonCharInEqualPairs] > (int)equalPairs.size() / 2) {
        std::vector<int> nonEqualPairsMinBeautyPenalties;
        for (int i = 0; i < n / 2; i++) {
            if (s[i] != s[n - 1 - i] && s[i] != mostCommonCharInEqualPairs && s[n - 1 - i] != mostCommonCharInEqualPairs) {
                nonEqualPairsMinBeautyPenalties.push_back(std::min(beauty[i], beauty[n - 1 - i]));
            }
        }
        std::sort(nonEqualPairsMinBeautyPenalties.begin(), nonEqualPairsMinBeautyPenalties.end());
        int rem = 2 * charOccurrencesInEqualPairs[(int)mostCommonCharInEqualPairs] - (int)equalPairs.size();
        for (int i = 0; i < rem; i++) {
            ans -= nonEqualPairsMinBeautyPenalties[i];
        }
    }

    cout << ans << "\n";
    return 0;
}

